import com.google.gson.JsonObject;
import dev.golem.harness.api.Client;
import dev.golem.harness.api.Expect;
import dev.golem.harness.api.Scenario;

import java.util.regex.Matcher;
import java.util.regex.Pattern;

/**
 * GitHub issue 110: a generated Desert Atom. Worldgen runs no onPlace, so its waste drums never ticked: a fresh one read
 * 0 to 2 RAD. The seeded world is reset so the structure is generated by this run, then the chunk radiation over the
 * barrels must rise past 1.7's fog threshold (100 RAD).
 */
public final class Gh110DesertAtomRadiation implements Scenario {

    private static final Pattern FOUND = Pattern.compile("nearest (hbm:[a-z0-9_]+) is at \\[(-?\\d+), ~, (-?\\d+)\\]");

    @Override
    public void run(Client c) throws Exception {
        c.useSeededWorld();
        c.resetWorld();
        c.waitInWorld(240_000L);
        c.markLog();
        c.cmd("locate structure hbm:desert_atom");
        c.waitTicks(200);
        Matcher matcher = null;
        for (String line : c.logSinceMark("nearest hbm:")) {
            Matcher m = FOUND.matcher(line);
            if (m.find()) matcher = m;
        }
        Expect.that(matcher != null, "/locate found a Desert Atom: " + c.logSinceMark("CHAT"));
        int x = Integer.parseInt(matcher.group(2)), z = Integer.parseInt(matcher.group(3));
        System.out.println("[Gh110] " + c.node() + " Desert Atom near " + x + ", " + z);

        c.cmd("gamemode creative");
        c.cmd("effect give @s minecraft:resistance 600 4 true");
        c.teleport(x + 8.5, 120, z + 12.5);
        c.waitTicks(200);
        double peak = 0;
        for (int i = 0; i < 12; i++) {
            c.waitTicks(200);
            JsonObject impact = c.query("hbm_impact", new JsonObject()).getAsJsonObject("server");
            peak = Math.max(peak, impact.get("chunk_rad").getAsDouble());
            System.out.println("[Gh110] " + c.node() + " tick " + (i + 1) * 200 + " chunk radiation " + impact.get("chunk_rad").getAsDouble());
        }
        c.screenshot("gh110-desert-atom");
        Expect.that(peak > 100, "the Desert Atom's barrels irradiate its chunk past 100 RAD: " + peak);
        c.useFlatWorld();
    }
}
